import { buildSchema, graphql } from "graphql";
const schema = buildSchema("type Query { score: Int! } type Mutation { setScore(value: Int!): Int! }");
let score = 3;
const rootValue = { score: () => score, setScore: ({ value }) => { score = value; return score; } };
const result = await graphql({ schema, rootValue, source: "mutation { setScore(value: 8) }", variableValues: {} });
console.log(JSON.stringify(result.data));
